export declare const comboStyles = "\n/* ---- \u5F39\u5C42\u5BB9\u5668\u4E0E\u641C\u7D22 / \u6807\u7B7E\u7B5B\u9009 ---- */\n.wf-combo-backdrop {\n  position: absolute;\n  z-index: 35;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  padding: 16px;\n  background: color-mix(in srgb, var(--wf-bg) 72%, transparent);\n  backdrop-filter: blur(4px);\n}\n\n.wf-combo {\n  width: min(1080px, 94%);\n  height: min(92%, 760px);\n  max-height: 92%;\n  display: flex;\n  flex-direction: column;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 14px;\n  background: var(--wf-layer);\n  box-shadow: 0 20px 60px color-mix(in srgb, var(--wf-ink) 18%, transparent);\n  overflow: hidden;\n}\n\n.wf-combo__search {\n  flex: none;\n  padding: 8px 12px 0;\n}\n\n.wf-combo__search input {\n  width: 100%;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 8px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 7px 10px;\n  outline: 0;\n}\n\n.wf-combo__search input:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-combo__tags {\n  flex: none;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n  padding: 8px 12px 0;\n}\n\n.wf-combo-tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 3px 10px;\n  border: 1px solid var(--wf-border);\n  border-radius: 999px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink-2);\n  font-size: 10px;\n  cursor: pointer;\n  transition: border-color .14s ease, background .14s ease, color .14s ease;\n}\n\n.wf-combo-tag:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-ink);\n}\n\n.wf-combo-tag.is-active {\n  border-color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 12%, var(--wf-layer-2));\n  color: var(--wf-brand);\n}\n\n.wf-combo-tag__bulk {\n  margin-left: auto;\n  border-color: var(--wf-border-strong);\n  background: color-mix(in srgb, var(--wf-brand) 8%, var(--wf-layer-2));\n  color: var(--wf-ink);\n  font-weight: 650;\n}\n\n.wf-combo-tag__bulk:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-brand);\n}\n\n.wf-combo-tag__bulk:disabled {\n  opacity: .45;\n  cursor: default;\n}\n\n/* ---- \u5F39\u5C42\u5934\u90E8 ---- */\n.wf-combo__head {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 12px 16px;\n  border-bottom: 1px solid var(--wf-border);\n}\n\n.wf-combo__head h3 {\n  margin: 0;\n  font-size: 14px;\n  color: var(--wf-ink);\n  flex: none;\n}\n\n.wf-combo__head .wf-status {\n  margin-left: 0;\n}\n\n.wf-combo__close {\n  margin-left: auto;\n}\n\n/* ---- \u76EE\u5F55\u533A\uFF08\u6807\u7B7E\u9875 + \u5361\u7247\u7F51\u683C\uFF09 ---- */\n.wf-combo__body {\n  flex: 1;\n  min-height: 0;\n  display: flex;\n  overflow: hidden;\n}\n\n.wf-combo__catalog {\n  flex: 1.35;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  border-right: 1px solid var(--wf-border);\n  overflow: hidden;\n  position: relative;\n  z-index: 2;\n}\n\n.wf-combo__tabs {\n  flex: none;\n  display: flex;\n  gap: 4px;\n  padding: 8px 10px 0;\n  border-bottom: 1px solid var(--wf-border);\n}\n\n.wf-combo__tab {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  border: 0;\n  border-radius: 9px 9px 0 0;\n  background: transparent;\n  color: var(--wf-ink-2);\n  padding: 7px 12px;\n  font-size: 11px;\n  font-weight: 650;\n  cursor: pointer;\n}\n\n.wf-combo__tab:hover {\n  color: var(--wf-ink);\n}\n\n.wf-combo__tab.is-active {\n  color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 10%, transparent);\n  box-shadow: inset 0 -2px 0 var(--wf-brand);\n}\n\n.wf-combo__tab-count {\n  padding: 1px 6px;\n  border-radius: 999px;\n  background: var(--wf-layer-2);\n  font-size: 9px;\n  color: var(--wf-ink-2);\n}\n\n.wf-combo__grid {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(228px, 1fr));\n  gap: 8px;\n  align-content: start;\n  padding: 12px;\n  scrollbar-width: thin;\n}\n\n.wf-combo-card {\n  display: flex;\n  gap: 9px;\n  align-items: flex-start;\n  text-align: left;\n  border: 1px solid var(--wf-border);\n  border-radius: 11px;\n  background: var(--wf-layer-2);\n  padding: 10px 11px;\n  cursor: pointer;\n  transition: border-color .14s ease, background .14s ease;\n  min-height: 96px;\n}\n\n.wf-combo-card:hover {\n  border-color: var(--wf-brand);\n}\n\n.wf-combo-card.is-checked {\n  border-color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 8%, var(--wf-layer-2));\n}\n\n.wf-combo-card.is-disabled {\n  opacity: .55;\n  cursor: default;\n  border-style: dashed;\n}\n\n.wf-combo-card.is-disabled .wf-combo-card__name {\n  color: var(--wf-ink-2);\n}\n\n.wf-combo-card input {\n  flex: none;\n  margin-top: 2px;\n  accent-color: var(--wf-brand);\n}\n\n/* \u5361\u7247\u4E3B\u533A\uFF08\u70B9\u51FB\u52FE\u9009\uFF09\u4E0E\u53F3\u4E0B\u89D2\u64CD\u4F5C\u533A\uFF1A\u6B64\u524D\u4E3A\u5185\u8054 style\uFF0C\u73B0\u6309\u8BED\u4E49\u7C7B\u540D\u8868\u8FBE */\n.wf-combo-card {\n  position: relative;\n}\n\n.wf-combo-card__main {\n  display: flex;\n  gap: 9px;\n  align-items: flex-start;\n  text-align: left;\n  border: 0;\n  background: transparent;\n  padding: 0 88px 30px 0;\n  flex: 1;\n  cursor: pointer;\n}\n\n.wf-combo-card__main:disabled {\n  cursor: default;\n}\n\n.wf-combo-card__actions {\n  display: flex;\n  gap: 4px;\n  position: absolute;\n  right: 8px;\n  bottom: 8px;\n}\n\n.wf-combo__grid-empty {\n  grid-column: 1 / -1;\n  padding: 14px;\n}\n\n.wf-combo-card__body {\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n}\n\n.wf-combo-card__name {\n  font-size: 12px;\n  font-weight: 650;\n  color: var(--wf-ink);\n  word-break: break-all;\n}\n\n.wf-combo-card__desc {\n  font-size: 10px;\n  line-height: 1.45;\n  color: var(--wf-ink-2);\n  display: -webkit-box;\n  -webkit-line-clamp: 3;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  word-break: break-word;\n}\n\n.wf-combo-card__badge {\n  display: inline-block;\n  align-self: flex-start;\n  padding: 1px 6px;\n  border-radius: 999px;\n  background: var(--wf-layer);\n  border: 1px solid var(--wf-border);\n  font-size: 8px;\n  color: var(--wf-ink-2);\n}\n\n/* ---- \u53F3\u4FA7\u8BE6\u60C5\u680F\uFF08\u6761\u76EE\u5217\u8868 / \u7F16\u8F91 / \u5DF2\u9009\u6E05\u5355\uFF09 ---- */\n.wf-combo__side {\n  flex: 1;\n  min-width: 290px;\n  max-width: 380px;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.wf-combo__side-head {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--wf-border);\n}\n\n.wf-combo__side-head h4 {\n  margin: 0;\n  font-size: 12px;\n  color: var(--wf-ink);\n  flex: 1;\n}\n\n.wf-combo__side-list {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding: 10px 14px;\n  scrollbar-width: thin;\n}\n\n.wf-combo-item {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  text-align: left;\n  border: 1px solid var(--wf-border);\n  border-radius: 10px;\n  background: var(--wf-layer-2);\n  padding: 8px 10px;\n  cursor: pointer;\n}\n\n.wf-combo-item:hover {\n  border-color: var(--wf-brand);\n}\n\n.wf-combo-item.is-active {\n  border-color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 8%, var(--wf-layer-2));\n}\n\n.wf-combo-item__label {\n  flex: 1;\n  min-width: 0;\n  font-size: 12px;\n  font-weight: 650;\n  color: var(--wf-ink);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.wf-combo-item__meta {\n  font-size: 9px;\n  color: var(--wf-ink-2);\n}\n\n.wf-combo__edit {\n  flex: none;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 12px 14px;\n  border-top: 1px solid var(--wf-border);\n}\n\n.wf-combo__edit label {\n  display: grid;\n  gap: 4px;\n  color: var(--wf-ink-2);\n  font-size: 11px;\n}\n\n.wf-combo__edit input {\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 6px 8px;\n  outline: 0;\n}\n\n.wf-combo__edit input:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-combo__selection {\n  flex: none;\n  max-height: 120px;\n  overflow: auto;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n  padding: 8px 14px;\n  border-top: 1px solid var(--wf-border);\n  scrollbar-width: thin;\n}\n\n.wf-combo-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 2px 8px;\n  border-radius: 999px;\n  background: color-mix(in srgb, var(--wf-brand) 10%, var(--wf-layer-2));\n  border: 1px solid color-mix(in srgb, var(--wf-brand) 35%, var(--wf-border));\n  font-size: 10px;\n  color: var(--wf-ink);\n}\n\n.wf-combo-chip button {\n  border: 0;\n  background: transparent;\n  color: var(--wf-ink-2);\n  cursor: pointer;\n  font-size: 10px;\n  line-height: 1;\n  padding: 0;\n}\n\n.wf-combo-chip button:hover {\n  color: var(--wf-err);\n}\n\n.wf-combo__side-foot {\n  flex: none;\n  display: flex;\n  gap: 7px;\n  padding: 10px 14px;\n  border-top: 1px solid var(--wf-border);\n}\n\n.wf-combo__side-foot .wf-btn {\n  flex: 1;\n  font-size: 11px;\n  padding: 6px 10px;\n}\n\n/* ---- MCP \u8868\u5355 ---- */\n.wf-mcp-form {\n  flex: none;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 12px 14px;\n  border-top: 1px solid var(--wf-border);\n}\n\n.wf-mcp-form label {\n  display: grid;\n  gap: 4px;\n  color: var(--wf-ink-2);\n  font-size: 11px;\n}\n\n.wf-mcp-form input {\n  width: 100%;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 6px 8px;\n  outline: 0;\n}\n\n.wf-mcp-form input:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-mcp-form__row {\n  display: flex;\n  gap: 6px;\n}\n\n.wf-mcp-form__row .wf-btn {\n  flex: 1;\n  font-size: 11px;\n  padding: 6px 10px;\n}\n\n/* MCP \u8868\u5355\u5185\u8054\u884C / \u5806\u53E0\u533A\uFF08\u6B64\u524D\u4E3A\u5185\u8054 style\uFF09 */\n.wf-mcp-form__inline {\n  display: flex;\n  gap: 8px;\n  padding: 0 14px 12px;\n}\n\n.wf-mcp-form__grow {\n  flex: 1;\n}\n\n.wf-mcp-form__stack {\n  display: grid;\n  gap: 8px;\n  padding: 0 14px 12px;\n}\n\n.wf-mcp-form__note {\n  align-self: center;\n  flex: 1;\n}\n\n.wf-combo__head--sub {\n  border-top: 1px solid var(--wf-border);\n  padding: 8px 14px;\n}\n\n.wf-mcp-import__body {\n  padding: 0 14px 12px;\n  display: grid;\n  gap: 8px;\n}\n\n.wf-mcp-import__text {\n  min-height: 150px;\n  padding: 8px;\n  border-radius: 8px;\n  border: 1px solid var(--wf-border-strong);\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 12px;\n}\n\n/* ---- \u5F39\u5C42\u53D8\u4F53\uFF08\u5BF9\u8BDD\u6846 / \u63D0\u793A\u884C\uFF09 ---- */\n.wf-combo--dialog {\n  max-width: 560px;\n  height: auto;\n  max-height: 82%;\n}\n\n.wf-hint--block {\n  font-size: 10px;\n  line-height: 1.5;\n  color: var(--wf-ink-2);\n}\n\n.wf-combo-hint {\n  flex: none;\n  padding: 8px 14px;\n  border-top: 1px solid var(--wf-border);\n  font-size: 10px;\n  color: var(--wf-ink-2);\n  line-height: 1.5;\n}\n";
